<?php
require_once __DIR__.'/MarketDataCorporateActionTraceabilitySpec.php';
final class MarketDataCorporateActionTraceabilityGate
{
 public static function validate(string $root,bool $bound=false): array { $rows=MarketDataCorporateActionTraceabilitySpec::rows($root); $mandatory=MarketDataCorporateActionTraceabilitySpec::mandatory($root); $reference=array_filter($rows,static function($r){return ($r['active']??'')==='YES'&&($r['primary_stage']??'')==='MD-B11'&&($r['coverage_requirement']??'')==='REFERENCE_ONLY';}); $pending=array_filter($rows,static function($r){return ($r['active']??'')==='YES'&&($r['primary_stage']??'')==='MD-B11'&&in_array(($r['applicability']??''),['MANDATORY_OR_CONDITIONAL','CONDITIONAL_PENDING','APPLICABILITY_PENDING'],true);}); $invalid=[]; foreach($mandatory as $r){$e=trim((string)($r['current_evidence_ids']??'')); if($bound){if(($r['coverage_status']??'')!=='SATISFIED'||!preg_match('/^E-MD-B11-A001-\\d{3}$/',$e))$invalid[]=$r['rule_id'];}else{if(($r['coverage_status']??'')!=='NOT_ASSESSED'||$e!=='')$invalid[]=$r['rule_id'];}} $errors=[]; if(count($mandatory)!==138)$errors[]='MANDATORY_DENOMINATOR_MISMATCH'; if(count($reference)!==273)$errors[]='REFERENCE_COUNT_MISMATCH'; if(count($pending)!==0)$errors[]='APPLICABILITY_PENDING_NONZERO'; if($invalid)$errors[]=$bound?'BOUND_MANDATORY_STATE_INVALID':'PREMATURE_MANDATORY_STATE'; return ['status'=>$errors===[]?'PASS':'FAIL','mode'=>$bound?'BOUND_CLOSURE':'PRE_RUNTIME','mandatory'=>count($mandatory),'reference'=>count($reference),'pending_applicability'=>count($pending),'invalid_mandatory_state'=>count($invalid),'errors'=>$errors]; }
}
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){$r=MarketDataCorporateActionTraceabilityGate::validate(dirname(__DIR__,5),in_array('--bound',$argv,true)); echo json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL; exit($r['status']==='PASS'?0:1);} 
